# General Intelligence, reasoning side: blood relations, directions, ranking,
# syllogisms, Venn diagrams (in words), calendar and clock, drawing inferences,
# critical thinking, problem solving, numerical operations, and the emotional
# and social intelligence items named in the CHSL syllabus.
SYL = "\nWhich conclusion(s) follow from the statements?"
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Blood relations", "Pointing to a woman in a photograph, Kavya said, \"She is the wife of my father's only brother.\" How is the woman related to Kavya?",
      ["Aunt", "Mother", "Sister", "Grandmother"],
      "Kavya's father's only brother is her uncle, and the uncle's wife is her aunt."),
    S(1, 2, "Directions", "Ravi walks 7 km west, turns left and walks 4 km, then turns left again and walks 7 km. Where is he now with respect to his starting point?",
      ["4 km south", "4 km north", "7 km south", "11 km west"],
      "Facing west, a left turn points him south, so he walks 4 km south. Another left points him east, and 7 km east cancels the 7 km west. He ends 4 km south of the start."),
    S(1, 1, "Ranking", "In a row of 37 children, Meena is 11th from the right end. What is her position from the left end?",
      ["27th", "26th", "28th", "25th"],
      "Position from the left = total - position from the right + 1 = 37 - 11 + 1 = 27."),
    S(1, 2, "Syllogism", "Statements: All doctors are graduates. Some graduates are singers.\nConclusions: I. Some doctors are singers. II. Some singers are graduates." + SYL,
      ["Only II follows", "Only I follows", "Both I and II follow", "Neither follows"],
      "'Some graduates are singers' can be reversed to 'some singers are graduates', so II follows. The singing graduates need not be doctors, so I does not follow."),
    S(1, 2, "Venn diagrams", "Which set of classes is best shown by three circles, each one completely inside the next?",
      ["Lucknow, Uttar Pradesh, India", "Teachers, Women, Mothers", "Rose, Lotus, Flower", "Dog, Cat, Animal"],
      "Lucknow is in Uttar Pradesh, which is in India, so each class lies wholly inside the next. In the other sets two classes are separate or overlap."),
    S(1, 2, "Calendar", "If 12 August of a year is a Wednesday, what day of the week is 2 September of the same year?",
      ["Wednesday", "Thursday", "Tuesday", "Saturday"],
      "August has 31 days, so 31 August is 19 days after 12 August and 2 September is 21 days after it. 21 days is exactly 3 weeks, so the day is again Wednesday."),
    S(1, 3, "Clock", "What is the angle between the hour hand and the minute hand of a clock at 2:20?",
      ["50 degrees", "40 degrees", "60 degrees", "70 degrees"],
      "At 2:20 the minute hand is at 120 degrees. The hour hand is at 2 x 30 + 20 x 0.5 = 70 degrees. The angle is 120 - 70 = 50 degrees."),
    S(1, 2, "Drawing inferences", "Statement: \"Book your train tickets early; seats fill up fast during the festival season.\"\nAssumptions: I. Many people travel during festivals. II. Trains run only in the festival season.\nWhich assumption(s) are implicit in the statement?",
      ["Only I is implicit", "Only II is implicit", "Both are implicit", "Neither is implicit"],
      "Seats fill fast only if many people travel, so I is assumed. Nothing suggests trains run only at festival time, so II is not."),
    S(1, 1, "Emotional intelligence", "A colleague makes a mistake that delays your shared work. What is the most appropriate response?",
      ["Talk calmly and fix it together", "Complain to everyone in office", "Redo the work and say nothing", "Refuse to work with them ever again"],
      "Raising the problem calmly and solving it together fixes the work and keeps the working relationship. Complaining or refusing to work together makes it worse."),
    S(1, 1, "Social intelligence", "A new student in your class does not yet speak the local language well. What should you do?",
      ["Help them and include them", "Laugh at their mistakes", "Avoid sitting near them", "Ask the teacher to move them"],
      "Including a newcomer and helping with the language is the socially intelligent response. The other options exclude or hurt the student."),
    S(1, 3, "Numerical operations", "Select the correct combination of mathematical signs to replace the * signs and balance the equation.\n\n8 * 4 * 2 * 6 = 28",
      ["x, +, -", "x, -, +", "+, x, +", "x, ÷, +"],
      "8 x 4 + 2 - 6 = 32 + 2 - 6 = 28. The others give 8 x 4 - 2 + 6 = 36, 8 + 4 x 2 + 6 = 22 and 8 x 4 ÷ 2 + 6 = 22."),
    S(1, 1, "Ordering", "A is taller than B. C is taller than A. D is shorter than B. Who is the tallest?",
      ["C", "A", "B", "D"],
      "From the statements, C > A > B > D in height, so C is the tallest."),

    # ---------- Practice Test 2 ----------
    S(2, 2, "Blood relations", "Q is the son of R. R is the brother of S. S is the mother of T. How is Q related to T?",
      ["Cousin", "Brother", "Nephew", "Uncle"],
      "Q's father R is the brother of T's mother S. Children of a brother and a sister are cousins."),
    S(2, 2, "Directions", "A man is facing south. He turns 90 degrees anticlockwise and then 45 degrees clockwise. Which direction is he facing now?",
      ["South-east", "North-east", "South-west", "East"],
      "From south, 90 degrees anticlockwise brings him to east. Turning 45 degrees clockwise from east brings him halfway back towards south: south-east."),
    S(2, 1, "Ranking", "Sohan is 9th from the top and 16th from the bottom in his class. How many students are in the class?",
      ["24", "25", "23", "26"],
      "Total = rank from top + rank from bottom - 1 = 9 + 16 - 1 = 24. Sohan is counted in both ranks, so 1 is taken away."),
    S(2, 2, "Syllogism", "Statements: Some cars are red. All red things are bright.\nConclusions: I. Some cars are bright. II. All cars are bright." + SYL,
      ["Only I follows", "Only II follows", "Both I and II follow", "Neither follows"],
      "The red cars are bright, so some cars are bright and I follows. Nothing is said about cars that are not red, so II does not follow."),
    S(2, 3, "Venn diagrams", "Which set of classes is best shown by two circles that partly overlap and a third circle separate from both?",
      ["Doctors, Women, Rivers", "Fruits, Mangoes, Apples", "Pens, Pencils, Erasers", "Kochi, Kerala, India"],
      "Some doctors are women, so those two circles overlap, and rivers share nothing with either. Mangoes and apples lie inside fruits; pens, pencils and erasers are all separate; Kochi, Kerala and India are nested."),
    S(2, 2, "Calendar", "How many days are there from 1 January to 31 March of a leap year, both days included?",
      ["91", "90", "92", "89"],
      "January has 31 days, February 29 in a leap year and March 31: 31 + 29 + 31 = 91."),
    S(2, 1, "Clock", "Through how many degrees does the hour hand of a clock turn in 2 hours 30 minutes?",
      ["75 degrees", "60 degrees", "90 degrees", "150 degrees"],
      "The hour hand turns 360 degrees in 12 hours, which is 30 degrees an hour. In 2.5 hours it turns 2.5 x 30 = 75 degrees. 150 degrees would be the minute hand's turn in 25 minutes."),
    S(2, 2, "Drawing inferences", "Statement: \"All the trains to Patna are full this week.\"\nConclusions: I. Some travellers to Patna may go by bus. II. The railways should stop all trains to Patna." + SYL,
      ["Only I follows", "Only II follows", "Both I and II follow", "Neither follows"],
      "If the trains are full, some people may take another mode of transport, so I follows. Full trains show demand, which is no reason to stop them, so II does not follow."),
    S(2, 1, "Emotional intelligence", "You feel angry after an argument with a friend. What is the best first step?",
      ["Calm down before you reply", "Send an angry message now", "Tell others about the fight", "Block the friend at once"],
      "Managing your own anger before responding is the core of emotional intelligence. The other options act on anger and usually make the situation worse."),
    S(2, 1, "Problem solving", "A clerk files 12 letters in 4 minutes. At the same rate, how many letters does she file in 30 minutes?",
      ["90", "80", "96", "72"],
      "She files 12 ÷ 4 = 3 letters a minute, so in 30 minutes she files 3 x 30 = 90."),
    S(2, 2, "Critical thinking", "Statement: \"Use our toothpaste for stronger teeth.\"\nAssumptions: I. People want stronger teeth. II. Toothpaste has no effect on teeth.\nWhich assumption(s) are implicit in the statement?",
      ["Only I is implicit", "Only II is implicit", "Both are implicit", "Neither is implicit"],
      "An advertisement promising stronger teeth assumes people want them, so I is implicit. II contradicts the claim the advertisement makes."),
    S(2, 3, "Seating arrangement", "Five friends P, Q, R, S and T sit in a row facing north. P is at the left end. R is in the middle. S is to the immediate right of P. T is not at the right end. Who is at the right end?",
      ["Q", "T", "S", "R"],
      "Seats 1 to 5 from the left: P is 1 and S is 2. R is 3. T is not at 5, so T is 4, leaving Q at 5, the right end."),

    # ---------- Drill only ----------
    S(0, 1, "Blood relations", "X is the brother of Y. Y is the daughter of Z. How is X related to Z?",
      ["Son", "Brother", "Nephew", "Father"],
      "Y is Z's daughter and X is Y's brother, so X is Z's son."),
    S(0, 2, "Directions", "Sunil walks 20 m east and then 21 m north. How far is he from his starting point?",
      ["29 m", "41 m", "1 m", "21 m"],
      "The two legs are at right angles, so the distance is the square root of 20 x 20 + 21 x 21 = 400 + 441 = 841, which is 29 m."),
    S(0, 1, "Ranking", "In a queue, Neha is 7th from the front and Gita is 4 places behind her. What is Gita's position from the front?",
      ["11th", "3rd", "10th", "12th"],
      "Behind means further from the front: 7 + 4 = 11th."),
    S(0, 2, "Syllogism", "Statements: No pencil is a pen. All pens are markers.\nConclusions: I. Some markers are not pencils. II. All markers are pens." + SYL,
      ["Only I follows", "Only II follows", "Both I and II follow", "Neither follows"],
      "The markers that are pens are not pencils, so some markers are not pencils and I follows. 'All pens are markers' cannot be reversed to 'all markers are pens', so II does not follow."),
]
